[CmdletBinding()]param([string]$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;Import-Module (Join-Path $root 'ES/Automation/ABCD/ESABCDPatchPlanning.psm1') -Force
$rel='ES/Automation/Contracts/es-abcd-capability-receipt-v1.schema.json';$target=Join-Path $root $rel;$before=(Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant();$candidate=[ordered]@{candidateId='approval-candidate';proposedChanges=@([ordered]@{path=$rel;afterContent='{}';changeId='approval-noop'})};$envelope=[ordered]@{schemaVersion=1;status='candidate';candidateSetHash=('f'*64);generationMode='engineering';candidates=@($candidate)}
$envPath=Join-Path $root 'ES/Output/StaticReplay/es-abcd-approval-envelope-test.json';$gatePath=Join-Path $root 'ES/Output/StaticReplay/es-abcd-final-gate-test.json';[IO.File]::WriteAllText($envPath,($envelope|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$serializedEnvelope=Get-Content -LiteralPath $envPath -Raw -Encoding UTF8|ConvertFrom-Json;$plan=New-ESABCDCandidatePatchPlan -CandidateEnvelope $serializedEnvelope -Scenario DesignChange -CurrentHead ('a'*40) -AuthorizationRef 'user:test' -SourceFiles @($rel) -AllowedWriteScopes @('ES/Automation/Contracts');$gate=[ordered]@{status='accepted';decisionStatus='Accepted';gateId='gate-test';planHash=$plan.planHash;candidateSetHash=$serializedEnvelope.candidateSetHash};[IO.File]::WriteAllText($gatePath,($gate|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false))
$bridge=Join-Path $root 'ES/Automation/ABCD/Invoke-ESABCDApprovedCandidateApply.ps1';$result=& $bridge -ProjectRoot $root -CandidateEnvelopePath $envPath -CandidateId approval-candidate -FinalGatePath $gatePath -ObservedHead ('a'*40) -ApplyAuthorizationRef user:test -Scenario DesignChange -AllowedWriteScopes @('ES/Automation/Contracts') -SourceFiles @($rel)|ConvertFrom-Json;$after=(Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant();$passed=([string]$result.status -ceq 'awaiting-explicit-apply' -and [string]$result.request.requestStatus -ceq 'awaiting-explicit-apply' -and $before -ceq $after)
[pscustomobject]@{status=if($passed){'passed'}else{'failed'};bridgeStatus=$result.status;requestStatus=$result.request.requestStatus;sourceUnchanged=($before -ceq $after);applyNotRequested=$true};if(-not $passed){exit 1}
